// 1. Zustand: Khởi tạo cực kỳ tinh gọn, không cần Provider
import { create } from 'zustand';

interface CartState {
  itemsCount: number;
  addItem: () => void;
  reset: () => void;
}

export const useCartStore = create<CartState>((set) => ({
  itemsCount: 0,
  addItem: () => set((state) => ({ itemsCount: state.itemsCount + 1 })),
  reset: () => set({ itemsCount: 0 }),
}));

// Trong Component: dùng trực tiếp như custom hook
export const CartBadge = () => {
  const count = useCartStore((state) => state.itemsCount);
  return <span>Giỏ hàng: {count}</span>;
};

import { create } from 'zustand';

interface UserSessionState {
  userId: string | null;
  isAuthenticated: boolean;
  login: (token: string, userId: string) => void;
  logout: () => void;
  getAuthHeader: () => string | null;
}

export const useUserSessionStore = create<UserSessionState>((set, get) => ({
  userId: null,
  isAuthenticated: false,
  login: (token, userId) => {
    localStorage.setItem('auth_token', token);
    set({ userId, isAuthenticated: true });
  },
  logout: () => {
    localStorage.removeItem('auth_token');
    // Shallow merge đặt lại trạng thái ban đầu
    set({ userId: null, isAuthenticated: false });
  },
  // Sử dụng get() để đọc snapshot state tức thời mà không gây re-render
  getAuthHeader: () => {
    const { isAuthenticated } = get();
    return isAuthenticated ? `Bearer ${localStorage.getItem('auth_token')}` : null;
  }
}));

// Cách truyền thống (Anti-pattern: Quá nhiều boilerplate và dễ dính race conditions)
