// Cách hiện đại với TanStack Query v5:
import { useQuery } from '@tanstack/react-query';

interface UserProfile {
  id: string;
  name: string;
  email: string;
}

export function UserProfileCard({ userId }: { userId: string }) {
  const { data: user, isLoading, isError } = useQuery<UserProfile>({
    queryKey: ['users', userId],
    queryFn: async () => {
      const res = await fetch(`/api/users/${userId}`);
      if (!res.ok) throw new Error('Không thể tải thông tin người dùng');
      return res.json();
    },
    staleTime: 1000 * 60 * 5, // Dữ liệu được coi là fresh trong 5 phút
  });

  if (isLoading) return <div>Đang tải skeleton...</div>;
  if (isError || !user) return <div>Lỗi khi tải dữ liệu!</div>;

  return <div>Xin chào, {user.name} ({user.email})</div>;
}

import { useQuery } from '@tanstack/react-query';

interface Article {
  id: string;
  title: string;
  content: string;
}

export function ArticleDetail({ articleId }: { articleId: string }) {
  const {
    data: article,
    isLoading, // True khi query lần đầu và chưa có cache
    isFetching, // True mỗi khi có network request ngầm
    isError,
    error,
    refetch
  } = useQuery<Article>({
    queryKey: ['articles', articleId], // queryKey dạng mảng phân cấp
    queryFn: async ({ signal }) => {
      // Nhận AbortSignal tự động hủy request khi unmount
      const res = await fetch(`/api/articles/${articleId}`, { signal });
      if (!res.ok) throw new Error('Bài viết không tồn tại');
      return res.json();
    },
    enabled: Boolean(articleId), // Chỉ fetch khi có articleId hợp lệ
    staleTime: 60 * 1000,        // Fresh trong 1 phút
    retry: 2,                    // Retry 2 lần nếu fail
  });

  if (isLoading) return <p>Đang tải bài viết...</p>;
  if (isError) return <p>Lỗi: {(error as Error).message}</p>;

  return (
    <article>
      <h1>{article?.title}</h1>
      <p>{article?.content}</p>
      {isFetching && <small>Đang đồng bộ dữ liệu mới nhất...</small>}
    </article>
  );
}

import React, { useState } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';

export function AppProviders({ children }: { children: React.ReactNode }) {
  // Tạo QueryClient instance an toàn, tránh khởi tạo lại mỗi lần re-render
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            staleTime: 1000 * 30, // Mặc định 30 giây
            refetchOnWindowFocus: false, // Tắt refetch khi focus lại tab nếu không cần
            retry: 1,
          },
        },
      })
  );

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      {/* Devtools chỉ kích hoạt trong môi trường development */}
      <ReactQueryDevtools initialIsOpen={false} />
    </QueryClientProvider>
  );
}

import { useQuery } from '@tanstack/react-query';

export function OrderList() {
  const { data: orders, isLoading, isFetching } = useQuery({
    queryKey: ['orders'],
    queryFn: async () => {
      const res = await fetch('/api/orders');
      return res.json();
    },
    staleTime: 1000 * 60, // 1 phút
  });

  // 1. Hard loading: Chưa có cache, bắt buộc hiển thị Skeleton
  if (isLoading) {
    return <div className="skeleton-loader">Đang tải danh sách đơn hàng...</div>;
  }

  // 2. Đã có cache: Render danh sách ngay lập tức, kèm indicator ngầm nếu đang fetch
  return (
    <div className="relative">
      <header className="flex justify-between items-center">
        <h2>Danh sách đơn hàng ({orders?.length})</h2>
        {isFetching && (
          <span className="text-xs text-blue-500 animate-pulse">
            Đang đồng bộ dữ liệu mới nhất...
          </span>
        )}
      </header>

      <ul>
        {orders?.map((order: any) => (
          <li key={order.id}>{order.code} - {order.total}đ</li>
        ))}
      </ul>
    </div>
  );
}

// Kiến trúc chuẩn Redux: Unidirectional Data Flow
// 1. Action: Mô tả sự kiện
const depositMoney = (amount: number) => ({
  type: 'bank/deposit' as const,
  payload: amount,
});

// 2. Reducer: Hàm thuần túy tính toán state mới
interface BankState {
  balance: number;
}

const initialState: BankState = { balance: 0 };

function bankReducer(state = initialState, action: ReturnType<typeof depositMoney>): BankState {
  switch (action.type) {
    case 'bank/deposit':
      // Không mutate: Trả về object mới hoàn toàn
      return { ...state, balance: state.balance + action.payload };
    default:
      return state;
  }
}

// Minh họa vi phạm vs tuân thủ 3 nguyên tắc:

// VI PHẠM Nguyên tắc 3 (Gây side-effect và mutate trực tiếp)
function badReducer(state: any, action: any) {
  if (action.type === 'ADD_ITEM') {
    state.items.push(action.payload); // Mutate trực tiếp!
    state.updatedAt = new Date().toISOString(); // Side-effect (không pure)!
    return state;
  }
  return state;
}

// TUÂN THỦ đúng chuẩn Redux:
function goodReducer(state = { items: [], updatedAt: 0 }, action: any) {
  switch (action.type) {
    case 'ADD_ITEM':
      return {
        ...state,
        items: [...state.items, action.payload], // Tạo mảng mới
        updatedAt: action.meta.timestamp,       // Nhận timestamp từ action payload/meta
      };
    default:
      return state;
  }
}

// Chuẩn hóa Action theo Flux Standard Action (FSA)
export interface FluxStandardAction<T = any, M = any> {
  type: string;
  payload?: T;
  error?: boolean;
  meta?: M;
}

// Action Creator: Hàm tạo action có type-safe
export const updateUsername = (newUsername: string): FluxStandardAction<string, { timestamp: number }> => ({
  type: 'user/updateUsername',
  payload: newUsername,
  meta: {
    timestamp: Date.now(),
  },
});

// Action biểu thị lỗi
export const fetchUserFailed = (error: Error): FluxStandardAction<Error> => ({
  type: 'user/fetchFailed',
  payload: error,
  error: true,
});

interface CartItem {
  id: string;
  title: string;
  quantity: number;
}

interface CartState {
  items: CartItem[];
}

const initialCartState: CartState = {
  items: [],
};

type CartAction =
  | { type: 'cart/addItem'; payload: CartItem }
  | { type: 'cart/removeItem'; payload: string }
  | { type: 'cart/clear' };

export function cartReducer(state = initialCartState, action: CartAction): CartState {
  switch (action.type) {
    case 'cart/addItem': {
      const existingIndex = state.items.findIndex(item => item.id === action.payload.id);
      if (existingIndex > -1) {
        // Cập nhật số lượng của item đã có (Immutability)
        const updatedItems = state.items.map((item, idx) =>
          idx === existingIndex ? { ...item, quantity: item.quantity + action.payload.quantity } : item
        );
        return { ...state, items: updatedItems };
      }
      return { ...state, items: [...state.items, action.payload] };
    }

    case 'cart/removeItem':
      return {
        ...state,
        items: state.items.filter(item => item.id !== action.payload),
      };

    case 'cart/clear':
      return initialCartState;

    default:
      // BẮT BUỘC: Giữ nguyên tham chiếu nếu action không liên quan
      return state;
  }
}

