'use client';

import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { useCallback } from 'react';

export function ProductFilters() {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  // Hàm cập nhật param lên URL một cách mượt mà
  const updateQueryString = useCallback(
    (name: string, value: string) => {
      const params = new URLSearchParams(searchParams.toString());
      if (value) {
        params.set(name, value);
      } else {
        params.delete(name);
      }
      // Reset về trang 1 khi đổi bộ lọc
      if (name !== 'page') params.set('page', '1');

      router.push(`${pathname}?${params.toString()}`, { scroll: false });
    },
    [searchParams, pathname, router]
  );

  return (
    <div className="filter-panel">
      <select
        value={searchParams.get('category') || ''}
        onChange={(e) => updateQueryString('category', e.target.value)}
      >
        <option value="">Tất cả danh mục</option>
        <option value="electronics">Điện tử</option>
        <option value="fashion">Thời trang</option>
      </select>

      <button onClick={() => updateQueryString('page', String(Number(searchParams.get('page') || 1) + 1))}>
        Trang kế tiếp
      </button>
    </div>
  );
}

// SO SÁNH BOILERPLATE:
// 1. Redux thuần: Cần file types.ts, actions.ts, reducer.ts riêng biệt kèm spread operators lồng nhau

// 2. Redux Toolkit (RTK): Tinh gọn trong một Slice duy nhất
import { createSlice, configureStore, PayloadAction } from '@reduxjs/toolkit';

interface CounterState {
  value: number;
}

const counterSlice = createSlice({
  name: 'counter',
  initialState: { value: 0 } as CounterState,
  reducers: {
    increment: (state) => {
      // Immer xử lý: Viết như mutating nhưng bên dưới tạo immutable snapshot
      state.value += 1;
    },
    incrementByAmount: (state, action: PayloadAction<number>) => {
      state.value += action.payload;
    },
  },
});

export const { increment, incrementByAmount } = counterSlice.actions;

export const store = configureStore({
  reducer: {
    counter: counterSlice.reducer,
  },
});

import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface AuthState {
  token: string | null;
  user: { id: string; email: string } | null;
  status: 'idle' | 'loading' | 'failed';
}

const initialState: AuthState = {
  token: null,
  user: null,
  status: 'idle',
};

export const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    // Tự sinh action auth/setToken
    setToken: (state, action: PayloadAction<string>) => {
      state.token = action.payload;
    },
    // Tự sinh action auth/logout
    logout: (state) => {
      state.token = null;
      state.user = null;
      state.status = 'idle';
    },
  },
  // Lắng nghe các action từ bên ngoài hoặc thunk
  extraReducers: (builder) => {
    // Giả sử có loginThunk từ file khác
    builder
      .addCase('auth/loginThunk/pending', (state) => {
        state.status = 'loading';
      })
      .addCase('auth/loginThunk/fulfilled', (state, action: any) => {
        state.status = 'idle';
        state.user = action.payload.user;
        state.token = action.payload.token;
      });
  },
});

import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';

interface UserData {
  id: string;
  name: string;
}

// 1. Định nghĩa thunk bất đồng bộ có kiểm soát lỗi
export const fetchUserById = createAsyncThunk<
  UserData,              // Kiểu dữ liệu trả về khi fulfilled
  string,                // Kiểu của tham số truyền vào (userId)
  { rejectValue: string } // Cấu hình rejectValue
>('users/fetchById', async (userId, { rejectWithValue, signal }) => {
  try {
    const response = await fetch(`/api/users/${userId}`, { signal });
    if (!response.ok) {
      return rejectWithValue('Không tìm thấy người dùng');
    }
    return (await response.json()) as UserData;
  } catch (err: any) {
    if (err.name === 'AbortError') return rejectWithValue('Request đã bị hủy');
    return rejectWithValue(err.message || 'Lỗi mạng không xác định');
  }
});

// 2. Xử lý 3 trạng thái lifecycle trong Slice
export const userSlice = createSlice({
  name: 'users',
  initialState: { data: null as UserData | null, loading: false, error: null as string | null },
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchUserById.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchUserById.fulfilled, (state, action) => {
        state.loading = false;
        state.data = action.payload;
      })
      .addCase(fetchUserById.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Đã có lỗi xảy ra';
      });
  },
});

import { createSelector } from '@reduxjs/toolkit';
import { RootState } from './store';

// 1. Input selectors (trích xuất state thô)
const selectOrderItems = (state: RootState) => state.orders.items;
const selectFilterStatus = (state: RootState) => state.orders.statusFilter;

// 2. Memoized selector: Chỉ tính toán lại khi items hoặc statusFilter đổi
export const selectFilteredOrders = createSelector(
  [selectOrderItems, selectFilterStatus],
  (items, filter) => {
    console.log('[Expensive Calculation]: Lọc đơn hàng');
    if (filter === 'ALL') return items;
    return items.filter((order) => order.status === filter);
  }
);

// 3. Derived selector tính toán tổng giá trị từ selector trên
export const selectTotalRevenue = createSelector(
  [selectFilteredOrders],
  (filteredOrders) =>
    filteredOrders.reduce((sum, order) => sum + order.amount, 0)
);

import { Middleware } from '@reduxjs/toolkit';

// Middleware ghi log thời gian thực thi của từng Action
export const performanceLoggerMiddleware: Middleware = (storeApi) => (next) => (action: any) => {
  const startTime = performance.now();

  console.group(`Action: ${action.type}`);
  console.log('State trước khi cập nhật:', storeApi.getState());

  // Chuyển action sang middleware tiếp theo hoặc vào reducer
  const result = next(action);

  console.log('State sau khi cập nhật:', storeApi.getState());
  console.log(`Thời gian xử lý: ${(performance.now() - startTime).toFixed(2)}ms`);
  console.groupEnd();

  return result;
};

