import { useSelector, useDispatch, TypedUseSelectorHook } from 'react-redux';
import { RootState, AppDispatch } from './store';

// 1. Tạo Typed Hooks cho toàn dự án
export const useAppDispatch: () => AppDispatch = useDispatch;
export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector;

// 2. Sử dụng trong Component với custom shallow comparison nếu return object
import { shallowEqual } from 'react-redux';

export const UserBadge = () => {
  const dispatch = useAppDispatch();

  // Chỉ re-render khi 'name' hoặc 'avatar' đổi (nhờ shallowEqual)
  const { name, avatar } = useAppSelector(
    (state) => ({
      name: state.user.profile.name,
      avatar: state.user.profile.avatar,
    }),
    shallowEqual
  );

  return (
    <div>
      <img src={avatar} alt={name} />
      <span>{name}</span>
    </div>
  );
};

import { create } from 'zustand';

interface CouponResponse {
  discountPercent: number;
  code: string;
}

interface CartStore {
  itemsCount: number;
  discount: number;
  isApplyingCoupon: boolean;
  errorMessage: string | null;
  // Synchronous Action
  increment: () => void;
  // Asynchronous Action
  applyCoupon: (code: string) => Promise<void>;
}

export const useCartStore = create<CartStore>((set, get) => ({
  itemsCount: 0,
  discount: 0,
  isApplyingCoupon: false,
  errorMessage: null,

  increment: () => set((state) => ({ itemsCount: state.itemsCount + 1 })),

  applyCoupon: async (code: string) => {
    // 1. Set trạng thái loading
    set({ isApplyingCoupon: true, errorMessage: null });
    try {
      const res = await fetch(`/api/coupons/${code}`);
      if (!res.ok) throw new Error('Mã giảm giá không hợp lệ');
      const data: CouponResponse = await res.json();

      // 2. Cập nhật state thành công
      set({ discount: data.discountPercent, isApplyingCoupon: false });
    } catch (err: any) {
      // 3. Xử lý lỗi
      set({ errorMessage: err.message, isApplyingCoupon: false });
    }
  },
}));

