import { create } from 'zustand';
import { useShallow } from 'zustand/react/shallow';
import { useEffect, useRef } from 'react';

const useGameStore = create<{ x: number; y: number; score: number }>((set) => ({
  x: 0,
  y: 0,
  score: 0,
}));

// Kỹ thuật 1: useShallow khi chọn nhiều props
export function CoordinatesBadge() {
  const { x, y } = useGameStore(
    useShallow((state) => ({ x: state.x, y: state.y }))
  );
  // Khi 'score' thay đổi -> Component này KHÔNG bị re-render!
  return <div>Vị trí: ({x}, {y})</div>;
}

// Kỹ thuật 2: Transient Update cho dữ liệu tần số cao (Zero React Render)
export function FastPosCanvas() {
  const boxRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Lắng nghe trực tiếp từ store, update DOM trực tiếp
    const unsub = useGameStore.subscribe((state) => {
      if (boxRef.current) {
        boxRef.current.style.transform = `translate3d(${state.x}px, ${state.y}px, 0)`;
      }
    });
    return unsub;
  }, []);

  return <div ref={boxRef} className="moving-box" />;
}

