import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

interface AuthStorageState {
  accessToken: string | null;
  refreshToken: string | null;
  tempSessionId: string | null; // Không muốn lưu vào localStorage
  setTokens: (access: string, refresh: string) => void;
  clearTokens: () => void;
}

export const useAuthStorageStore = create<AuthStorageState>()(
  persist(
    (set) => ({
      accessToken: null,
      refreshToken: null,
      tempSessionId: null,
      setTokens: (accessToken, refreshToken) => set({ accessToken, refreshToken }),
      clearTokens: () => set({ accessToken: null, refreshToken: null }),
    }),
    {
      name: 'secure_auth_cache',
      storage: createJSONStorage(() => localStorage),
      // Chỉ lưu trữ accessToken & refreshToken, bỏ qua tempSessionId
      partialize: (state) => ({
        accessToken: state.accessToken,
        refreshToken: state.refreshToken,
      }),
      version: 1,
      migrate: (persistedState: any, version: number) => {
        if (version === 0) {
          // Xử lý migrate dữ liệu từ schema cũ lên schema mới
          persistedState.refreshToken = null;
        }
        return persistedState;
      },
    }
  )
);

import { useMutation, useQueryClient } from '@tanstack/react-query';

interface Todo {
  id: string;
  title: string;
  completed: boolean;
}

export function useToggleTodo() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (todo: Todo) => {
      const res = await fetch(`/api/todos/${todo.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ completed: !todo.completed }),
      });
      if (!res.ok) throw new Error('Cập nhật thất bại');
      return res.json();
    },
    // 1. Chạy ngay khi bấm nút: Cập nhật UI lập tức
    onMutate: async (todoToToggle) => {
      await queryClient.cancelQueries({ queryKey: ['todos'] });
      const previousTodos = queryClient.getQueryData<Todo[]>(['todos']);

      queryClient.setQueryData<Todo[]>(['todos'], (old = []) =>
        old.map((t) => (t.id === todoToToggle.id ? { ...t, completed: !t.completed } : t))
      );

      // Trả về context để rollback nếu lỗi
      return { previousTodos };
    },
    // 2. Rollback nếu có lỗi
    onError: (err, newTodo, context) => {
      if (context?.previousTodos) {
        queryClient.setQueryData(['todos'], context.previousTodos);
      }
    },
    // 3. Đồng bộ lại dữ liệu thực tế từ server
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ['todos'] });
    },
  });
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

export function useCreatePost() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (newPostData: { title: string; content: string }) =>
      fetch('/api/posts', { method: 'POST', body: JSON.stringify(newPostData) }).then(r => r.json()),

    onSuccess: (createdPost) => {
      // 1. Fuzzy Invalidation: Vô hiệu hóa tất cả queries có prefix là ['posts']
      queryClient.invalidateQueries({
        queryKey: ['posts'],
      });

      // 2. Exact Invalidation: Chỉ vô hiệu hóa đúng danh sách trang 1
      queryClient.invalidateQueries({
        queryKey: ['posts', 'list', { page: 1 }],
        exact: true,
      });

      // 3. Predicate: Invalidation có điều kiện phức tạp
      queryClient.invalidateQueries({
        predicate: (query) =>
          query.queryKey[0] === 'posts' && query.state.dataUpdatedAt < Date.now() - 60000,
      });
    },
  });
}

