import { QueryClient, QueryCache, useQuery } from '@tanstack/react-query';
import { toast } from 'sonner';

// 1. Cấu hình Global Error Handler ở tầng QueryCache
export const queryClient = new QueryClient({
  queryCache: new QueryCache({
    onError: (error: any, query) => {
      // Chỉ hiển thị toast cho những query không xử lý lỗi ngầm
      if (query.meta?.showGlobalToast !== false) {
        toast.error(`Lỗi tải dữ liệu: ${error.message}`);
      }
    },
  }),
});

// 2. Component sử dụng Error Boundary (throwOnError)
export function CriticalUserProfile({ id }: { id: string }) {
  const { data: user } = useQuery({
    queryKey: ['user', id],
    queryFn: async () => {
      const res = await fetch(`/api/users/${id}`);
      if (!res.ok) throw new Error('Không thể tải profile');
      return res.json();
    },
    // Ném lỗi lên Error Boundary gần nhất thay vì quản lý if (isError) bằng tay
    throwOnError: true,
  });

  return <div>Hồ sơ: {user.name}</div>;
}

