// JOTAI: Định danh bằng Object Reference, không cần string key
import { atom, useAtom } from 'jotai';

// 1. Primitive atom
export const countAtom = atom(0);

// 2. Derived atom (tự động tính toán khi countAtom đổi)
export const doubleCountAtom = atom((get) => get(countAtom) * 2);

// Trong Component:
export function CounterComponent() {
  const [count, setCount] = useAtom(countAtom);
  const [double] = useAtom(doubleCountAtom);

  return (
    <button onClick={() => setCount((c) => c + 1)}>
      Count: {count} (Double: {double})
    </button>
  );
}

import { atom, useAtomValue, useSetAtom } from 'jotai';

interface CartItem {
  id: string;
  name: string;
  price: number;
}

// 1. Primitive Atom: Danh sách sản phẩm
export const cartItemsAtom = atom<CartItem[]>([]);

// 2. Read-only Derived Atom: Tính tổng tiền
export const totalPriceAtom = atom((get) => {
  const items = get(cartItemsAtom);
  return items.reduce((sum, item) => sum + item.price, 0);
});

// 3. Write-only Action Atom: Thêm sản phẩm
export const addToCartAtom = atom(null, (get, set, newItem: CartItem) => {
  const current = get(cartItemsAtom);
  set(cartItemsAtom, [...current, newItem]);
});

// Component hiển thị tổng tiền (Chỉ subscribe vào totalPriceAtom)
export function CartTotalBadge() {
  const total = useAtomValue(totalPriceAtom);
  return <div>Tổng: {total.toLocaleString()}đ</div>;
}

// Component nút bấm thêm hàng (KHÔNG subscribe dữ liệu -> KHÔNG re-render khi giỏ hàng đổi)
export function AddToCartButton({ product }: { product: CartItem }) {
  const addToCart = useSetAtom(addToCartAtom);
  return <button onClick={() => addToCart(product)}>Thêm vào giỏ</button>;
}

