import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

export const todoSlice = createSlice({
  name: 'todos',
  initialState: [] as Todo[],
  reducers: {
    // 1. Mutate draft an toàn qua Immer Proxy
    addTodo: (state, action: PayloadAction<string>) => {
      // Immer bẫy phương thức .push() và tạo bản sao mới phía sau hậu trường
      state.push({ id: Math.random().toString(), text: action.payload, done: false });
    },

    // 2. Return giá trị mới hoàn toàn (Không mutate)
    clearAll: () => {
      return []; // Hợp lệ: Return state mới
    },

    // 3. CẢNH BÁO BẪY: Vừa mutate vừa return -> LỖI!
    // badReducer: (state) => {
    //   state.push({ ... });
    //   return state; // RUNTIME ERROR: An immer producer returned a new value AND also made mutations!
    // }
  },
});

import { useQuery, useQueryClient } from '@tanstack/react-query';

interface Product {
  id: string;
  name: string;
  price: number;
  fullDescription?: string;
}

export function ProductDetail({ productId }: { productId: string }) {
  const queryClient = useQueryClient();

  // Kỹ thuật dùng placeholderData trích xuất từ cache danh sách:
  const { data, isPlaceholderData } = useQuery<Product>({
    queryKey: ['product', productId],
    queryFn: () => fetch(`/api/products/${productId}`).then(r => r.json()),

    placeholderData: () => {
      // Tìm sản phẩm trong danh sách đã tải trước đó để làm preview tạm thời
      const listData = queryClient.getQueryData<Product[]>(['products', 'list']);
      return listData?.find((p) => p.id === productId);
    },
  });

  return (
    <div style={{ opacity: isPlaceholderData ? 0.6 : 1 }}>
      <h1>{data?.name}</h1>
      <p>{data?.price}đ</p>
      {/* Khi query fetch xong, fullDescription mới xuất hiện */}
      <p>{data?.fullDescription || 'Đang tải thông tin chi tiết...'}</p>
    </div>
  );
}

import { useQuery } from '@tanstack/react-query';
import { useCallback } from 'react';

interface FullUserResponse {
  id: string;
  name: string;
  email: string;
  unreadNotificationsCount: number;
  preferences: Record<string, any>;
}

export function NotificationBadge({ userId }: { userId: string }) {
  // Component này CHỈ quan tâm đến số lượng thông báo chưa đọc
  const { data: count } = useQuery({
    queryKey: ['user', userId],
    queryFn: () => fetch(`/api/users/${userId}`).then(r => r.json() as Promise<FullUserResponse>),

    // Trích xuất đúng số lượng; memoize selector để tối ưu reference
    select: useCallback((user: FullUserResponse) => user.unreadNotificationsCount, []),
  });

  // Nếu user đổi tên hay đổi email -> Component này KHÔNG re-render!
  return <div className="badge">Chưa đọc: {count ?? 0}</div>;
