import { useQueries } from '@tanstack/react-query';

interface User {
  id: string;
  name: string;
}

export function UserComparisonView({ userIds }: { userIds: string[] }) {
  // Fetch song song mảng dynamic ID tuân thủ Rules of Hooks
  const { data: users, isPending } = useQueries({
    queries: userIds.map((id) => ({
      queryKey: ['user', id],
      queryFn: () => fetch(`/api/users/${id}`).then(r => r.json() as Promise<User>),
      staleTime: 60 * 1000,
    })),
    // Option combine trong v5 giúp gom kết quả sạch sẽ
    combine: (results) => ({
      data: results.map((result) => result.data).filter(Boolean) as User[],
      isPending: results.some((result) => result.isPending),
      isError: results.some((result) => result.isError),
    }),
  });

  if (isPending) return <div>Đang tải thông tin các users...</div>;

  return (
    <ul>
      {users.map((u) => (
        <li key={u.id}>{u.name}</li>
      ))}
    </ul>
  );
}

import { useQuery } from '@tanstack/react-query';

export function HeavyAnalyticsReport({ reportId }: { reportId: string }) {
  const { data, isLoading } = useQuery({
    queryKey: ['report', reportId],
    // Trích xuất thuộc tính signal từ context của queryFn
    queryFn: async ({ signal }) => {
      const response = await fetch(`/api/reports/${reportId}/heavy-download`, {
        signal, // Chuyển tiếp signal tới fetch API của trình duyệt
      });

      if (!response.ok) throw new Error('Không thể tải báo cáo');
      return response.json();
    },
  });

  if (isLoading) return <div>Đang tải báo cáo dung lượng lớn...</div>;
  return <div>{JSON.stringify(data)}</div>;
}

import { useQuery, keepPreviousData } from '@tanstack/react-query';
import { useState } from 'react';

export function PaginatedOrdersTable() {
  const [page, setPage] = useState(1);

  const { data, isPlaceholderData, isFetching } = useQuery({
    queryKey: ['orders', { page }],
    queryFn: () => fetch(`/api/orders?page=${page}`).then(r => r.json()),
    // Giữ nguyên dữ liệu trang cũ cho đến khi dữ liệu trang mới tải xong
    placeholderData: keepPreviousData,
  });

  return (
    <div>
      {/* Bảng dữ liệu: Làm mờ nhẹ khi đang tải dữ liệu trang mới */}
      <table style={{ opacity: isPlaceholderData ? 0.6 : 1, transition: 'opacity 0.2s' }}>
        <tbody>
          {data?.items.map((order: any) => (
            <tr key={order.id}><td>{order.code}</td><td>{order.total}đ</td></tr>
          ))}
        </tbody>
      </table>

      <div className="flex gap-2 items-center mt-4">
        <button disabled={page === 1} onClick={() => setPage(p => p - 1)}>Trang trước</button>
        <span>Trang {page}</span>
        <button
          disabled={isPlaceholderData || !data?.hasMore}
          onClick={() => setPage(p => p + 1)}
        >
          Trang sau
        </button>
        {isFetching && <small>Đang tải...</small>}
      </div>
    </div>
  );
}

import { useQuery } from '@tanstack/react-query';

export function OrganizationDashboard({ userEmail }: { userEmail: string }) {
  // Query 1: Lấy thông tin user để có organizationId
  const { data: user } = useQuery({
    queryKey: ['user', userEmail],
    queryFn: () => fetch(`/api/users?email=${userEmail}`).then(r => r.json()),
  });

  const orgId = user?.organizationId;

  // Query 2: Dependent Query - CHỈ fetch khi orgId đã tồn tại!
  const { data: orgDetails, isLoading: isOrgLoading } = useQuery({
    queryKey: ['organization', orgId],
    queryFn: () => fetch(`/api/organizations/${orgId}`).then(r => r.json()),
    // Ngăn chặn query chạy với orgId undefined
    enabled: Boolean(orgId),
  });

  if (!user) return <div>Đang định danh người dùng...</div>;
  if (isOrgLoading) return <div>Đang tải chi tiết tổ chức...</div>;

  return <div>Tổ chức: {orgDetails?.name}</div>;
}

