  tagTypes: ['Posts'],
  endpoints: (builder) => ({
    // Tự động sinh hook useGetPostsQuery
    getPosts: builder.query<Post[], void>({
      query: () => 'posts',
      providesTags: ['Posts'],
    }),
    // Tự động sinh hook useAddPostMutation
    addPost: builder.mutation<Post, Partial<Post>>({
      query: (body) => ({ url: 'posts', method: 'POST', body }),
      // Tự động kích hoạt refetch lại getPosts khi mutation thành công!
