import { useInfiniteQuery } from '@tanstack/react-query';
import { useEffect, useRef } from 'react';

export function InfinitePostFeed() {
  const loadMoreRef = useRef<HTMLDivElement>(null);

  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading,
  } = useInfiniteQuery({
    queryKey: ['posts-feed'],
    queryFn: async ({ pageParam = 1 }) => {
      const res = await fetch(`/api/feed?page=${pageParam}&limit=10`);
      return res.json(); // Trả về { items: [...], nextPage: number | null }
    },
    initialPageParam: 1,
    getNextPageParam: (lastPage) => lastPage.nextPage ?? undefined,
  });

  // Tự động tải trang tiếp khi cuộn tới sentinel div
  useEffect(() => {
    if (!hasNextPage || isFetchingNextPage) return;
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) fetchNextPage();
    });
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => observer.disconnect();
  }, [hasNextPage, isFetchingNextPage, fetchNextPage]);

  if (isLoading) return <div>Đang tải bảng tin...</div>;

  return (
    <div>
      {data?.pages.map((page, pageIndex) => (
        <div key={pageIndex}>
          {page.items.map((post: any) => (
            <article key={post.id} className="p-4 border-b">{post.title}</article>
          ))}
        </div>
      ))}

      <div ref={loadMoreRef} className="py-4 text-center">
        {isFetchingNextPage ? 'Đang tải thêm...' : hasNextPage ? 'Cuộn để tải thêm' : 'Đã tải hết bài viết!'}
      </div>
    </div>
  );
}

