import { useMutation, useQueryClient } from '@tanstack/react-query';

interface Comment {
  id: string;
  text: string;
}

export function useAddComment(postId: string) {
  const queryClient = useQueryClient();
  const queryKey = ['comments', postId];

  return useMutation({
    mutationFn: (newText: string) =>
      fetch(`/api/posts/${postId}/comments`, {
        method: 'POST',
        body: JSON.stringify({ text: newText }),
      }).then((r) => r.json()),

    // 1. Thực hiện ngay khi gửi request
    onMutate: async (newText) => {
      await queryClient.cancelQueries({ queryKey });

      // Lưu snapshot trước khi cập nhật
      const previousComments = queryClient.getQueryData<Comment[]>(queryKey) || [];

      // Cập nhật lạc quan (Optimistic update)
      const optimisticComment: Comment = { id: `temp-${Date.now()}`, text: newText };
      queryClient.setQueryData<Comment[]>(queryKey, [...previousComments, optimisticComment]);

      // Trả về context rollback
      return { previousComments };
    },

    // 2. Rollback nếu server trả lỗi
    onError: (err, newText, context) => {
      if (context?.previousComments) {
        queryClient.setQueryData(queryKey, context.previousComments);
      }
    },

    // 3. Luôn luôn invalidate để đồng bộ với server thật
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey });
    },
  });
}

