// 2. JOTAI (Atomic Graph): Phù hợp Canvas / Node-based editor
import { atom } from 'jotai';

// 1000 nodes trên canvas, mỗi node là 1 atom độc lập:
export const createNodeAtom = (x: number, y: number) => atom({ x, y });

// Di chuyển node A: CHỈ DUY NHẤT component render node A re-render!
// Hoàn toàn không ảnh hưởng đến 999 nodes còn lại (Zero selector overhead)

import { atom, useAtom } from 'jotai';

// Mô phỏng Ô tính bảng tính (Spreadsheet Cell)
export const cellA1Atom = atom(10);
export const cellA2Atom = atom(20);

// Công thức ô A3 = A1 + A2 (Derived Atom tự động đồng bộ)
export const cellA3FormulaAtom = atom((get) => get(cellA1Atom) + get(cellA2Atom));

export function SpreadsheetRow() {
  const [a1, setA1] = useAtom(cellA1Atom);
  const [a2] = useAtom(cellA2Atom);
  const [a3] = useAtom(cellA3FormulaAtom);

  return (
    <div className="flex gap-2">
      <input type="number" value={a1} onChange={(e) => setA1(Number(e.target.value))} />
      <span>+ {a2} =</span>
      <strong>{a3}</strong>
    </div>
  );
}

import { useQueryClient } from '@tanstack/react-query';

export function useAuthActions() {
  const queryClient = useQueryClient();

  const handleLogout = async () => {
    // 1. Hủy tất cả các request đang gửi dở dang
    await queryClient.cancelQueries();

    // 2. Query Filter: Xóa sạch toàn bộ dữ liệu cá nhân nhạy cảm
    queryClient.removeQueries({
      predicate: (query) => {
        const firstKey = query.queryKey[0];
        // Giữ lại dữ liệu tĩnh ('public-config'), xóa mọi thứ liên quan đến 'user', 'orders', 'cart'
        return ['user', 'orders', 'cart'].includes(String(firstKey));
      },
    });

    // 3. Query Filter: Chỉ refetch các query đang active trên giao diện công khai
    await queryClient.invalidateQueries({
      type: 'active',
      stale: true,
    });
  };

  return { handleLogout };
}

