// Lưu trữ Offline vào IndexedDB
const indexedDBPersister = createAsyncStoragePersister({
  storage: {
    getItem: (key) => get(key),
    setItem: (key, value) => set(key, value),
    removeItem: (key) => del(key),
  },
});

// Kích hoạt persistence cho toàn bộ QueryClient
persistQueryClient({
  queryClient,
  persister: indexedDBPersister,
  maxAge: 1000 * 60 * 60 * 24, // Dữ liệu offline có giá trị trong 24 giờ
  buster: 'v1.0.0', // Đổi buster khi thay đổi schema API để xóa cache cũ
});

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';

export function useDeleteProduct() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (productId: string) =>
      fetch(`/api/products/${productId}`, { method: 'DELETE' }).then((r) => r.json()),

    // 1. Chạy đầu tiên
    onMutate: async (productId) => {
      console.log('1. Bắt đầu xóa:', productId);
      return { startTime: Date.now() }; // Trả về context
    },

    // 2a. Chạy nếu thành công
    onSuccess: (data, productId, context) => {
      console.log(`2a. Xóa thành công sau ${Date.now() - context.startTime}ms`);
      toast.success('Đã xóa sản phẩm thành công');
    },

    // 2b. Chạy nếu thất bại
    onError: (error: any, productId, context) => {
      console.error('2b. Lỗi xảy ra:', error.message);
      toast.error('Không thể xóa sản phẩm');
    },

    // 3. Luôn chạy sau cùng
    onSettled: (data, error, productId, context) => {
      console.log('3. Hoàn tất chu kỳ mutation');
      queryClient.invalidateQueries({ queryKey: ['products'] });
    },
  });
}

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
import React, { useState } from 'react';

export function AppQueryProvider({ children }: { children: React.ReactNode }) {
  const [queryClient] = useState(() => new QueryClient());

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      {/* Tự động loại bỏ hoàn toàn trong Production build */}
      {process.env.NODE_ENV === 'development' && (
        <ReactQueryDevtools
          initialIsOpen={false}
          buttonPosition="bottom-right"
        />
      )}
    </QueryClientProvider>
  );
}

import { useQuery } from '@tanstack/react-query';
import { useState } from 'react';

export function LiveSearchInput() {
  const [searchTerm, setSearchTerm] = useState('react');

  // TanStack Query bảo đảm ZERO Race Condition:
  const { data: searchResults, isFetching } = useQuery({
    queryKey: ['search', searchTerm], // Khi searchTerm đổi -> queryKey đổi
    queryFn: async ({ signal }) => {
      // Truyền signal để hủy ngay request tìm kiếm cũ nếu người dùng gõ từ mới
      const res = await fetch(`/api/search?q=${encodeURIComponent(searchTerm)}`, { signal });
      return res.json();
    },
    staleTime: 30 * 1000,
  });

  return (
    <div>
      <input value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      {isFetching && <small>Đang tìm kiếm...</small>}
      <ul>
        {searchResults?.map((item: any) => (
          <li key={item.id}>{item.title}</li>
        ))}
      </ul>
    </div>
  );
}

