// 2. TanStack Query: Hướng đối tượng, Key phân cấp mạnh mẽ
import { useQuery } from '@tanstack/react-query';

export function UserProfile() {
  const { data, isPending, error } = useQuery({
    queryKey: ['user', 'profile'],
    queryFn: () => fetch('/api/user').then((r) => r.json()),
    staleTime: 60 * 1000,
  });

  if (isPending) return <div>Đang tải...</div>;
  return <div>{data?.name}</div>;
}

import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';

// createAsyncThunk: Dành cho luồng thanh toán nhiều bước + chống gọi trùng
export const processCheckoutThunk = createAsyncThunk<
  { orderId: string },
  { cartId: string },
  { state: { checkout: { isProcessing: boolean } } }
>(
  'checkout/process',
  async ({ cartId }, { thunkAPI }) => {
    // Luồng phức tạp: Gọi API thanh toán -> Trừ điểm ví -> Lưu audit log
    const res = await fetch('/api/checkout', {
      method: 'POST',
      body: JSON.stringify({ cartId }),
      signal: thunkAPI.signal,
    });
    return res.json();
  },
  {
    // CHỐNG DOUBLE-FETCH: Nếu đang xử lý thì hủy luôn lệnh dispatch mới!
    condition: (_, { getState }) => {
      const { isProcessing } = getState().checkout;
      if (isProcessing) {
        console.warn('Đang có tiến trình thanh toán, bỏ qua request trùng!');
        return false;
      }
      return true;
    },
  }
);

'use client';

import { type ReactNode, createContext, useRef, useContext } from 'react';
import { createStore, useStore } from 'zustand';

// 1. Định nghĩa kiểu và Store Factory Function
interface UserStore {
  username: string;
  setUsername: (name: string) => void;
}

const createUserStore = (initialName: string = 'Guest') => {
  return createStore<UserStore>()((set) => ({
    username: initialName,
    setUsername: (name) => set({ username: name }),
  }));
};

type UserStoreApi = ReturnType<typeof createUserStore>;
const UserStoreContext = createContext<UserStoreApi | undefined>(undefined);

// 2. Provider độc lập cho mỗi Request / Subtree
export function UserStoreProvider({
  children,
  initialName,
}: {
  children: ReactNode;
  initialName: string;
}) {
  const storeRef = useRef<UserStoreApi>();
  if (!storeRef.current) {
    // Khởi tạo instance độc lập, an toàn tuyệt đối trong SSR
    storeRef.current = createUserStore(initialName);
  }

  return (
    <UserStoreContext.Provider value={storeRef.current}>
      {children}
    </UserStoreContext.Provider>
  );
}

// 3. Custom Hook an toàn
export function useUserStoreContext<T>(selector: (state: UserStore) => T): T {
  const store = useContext(UserStoreContext);
  if (!store) throw new Error('useUserStoreContext phải được bọc trong UserStoreProvider');
  return useStore(store, selector);
}
